"""Copy for the sub-inner pages (one page per service in the header menus).

Every page follows the locked sub-inner structure (see ecommerce-website-development.html).
`source` says where a page's copy came from:
  'live'    — built from the matching squarezix.com page (services, why, FAQs …)
  'written' — no live page exists; Claude wrote the copy in the site's style.
Written pages are placeholders to review/replace when the design system is finalised;
build_service_pages.py prints the list on every build.

Node cards: (title, tag, description, [keywords]). Feature cards: (title, lead, [chips]).
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from live_content import LIVE as L  # noqa: E402


def lv(key, sec, title):
    """A description exactly as written on the live page."""
    return next(d for t, d, _b in L[key][sec]['items'] if t == title)


def live_nodes(key, sec, tag, kws=None, only=None):
    """Node cards straight from a live section (optionally a subset, with keywords)."""
    kws = kws or {}
    return [(t, tag, d, kws.get(t, [])) for t, d, _b in L[key][sec]['items'] if only is None or t in only]


def why_pick(key, sec, titles):
    items = {t: d for t, d, _b in L[key][sec]['items']}
    return [(t, items[t]) for t in titles]


